### JavaScript for gsap.matchMedia() with ScrollTrigger

Source: https://gsap.com/docs/v3/GSAP/gsap.matchMedia%28%29

JavaScript code that uses gsap.matchMedia() to define conditions for desktop and mobile based on viewport width and prefers-reduced-motion. It sets up a ScrollTrigger timeline and a non-ScrollTrigger animation, with an optional cleanup function.

```javascript
gsap.registerPlugin(ScrollTrigger);

let mm = gsap.matchMedia(),
    breakPoint = 800;

mm.add({
  // set up any number of arbitrarily-named conditions. The function below will be called when ANY of them match.
  isDesktop: `(min-width: ${breakPoint}px) and (prefers-reduced-motion: no-preference)`,
  isMobile: `(max-width: ${breakPoint - 1}px) and (prefers-reduced-motion: no-preference)`
}, (context) => {
  // context.conditions has a boolean property for each condition defined above indicating if it's matched or not.
  let { isDesktop, isMobile } = context.conditions,
      target = isDesktop ? ".desktop" : ".mobile",
      tl = gsap.timeline({
        scrollTrigger: {
          trigger: ".gray",
          scrub: 1,
          end: "200%",
          pin: true
        }
      });
  tl.to(target, {scale: 2, rotation: 360})
    .to(target, {scale: 1});

  // works for non-ScrollTrigger animations too: 
  gsap.to(target, {backgroundColor: "#2c7ad2", duration: 0.8, ease: "none", repeat: -1, yoyo: true});

  return () => { 
    // optionally return a cleanup function that will be called when the media query no longer matches
  }
});
```

